import type { Grade } from './types'

/**
 * Math scope & sequence — one topic per grade per week.
 * K and 1st align with Common Core (K.CC, K.OA, K.NBT, K.MD, K.G; 1.OA, 1.NBT,
 * 1.MD, 1.G). Money is included in 1st grade by family request (it is a 2nd
 * grade standard, so it is taught concretely). Pre-K follows early learning
 * guidelines: counting, cardinality, shapes, patterns, sorting, comparing.
 *
 * Every topic carries:
 *  - a parent teaching guide (objective / materials / teach / practice / check / next steps)
 *  - an `easy` activity using household objects for Minimum days
 *  - a worksheet generator spec — numbers are generated and answer keys are
 *    computed, never typed by hand.
 */

export type ShapeName = 'circle' | 'square' | 'triangle' | 'rectangle' | 'hexagon' | 'oval' | 'rhombus'

export type MathGen =
  | { kind: 'count-circle'; min: number; max: number }
  | { kind: 'count-write'; min: number; max: number }
  | { kind: 'trace-numbers'; from: number; to: number }
  | { kind: 'shape-find'; shapes: ShapeName[] }
  | { kind: 'shape-attributes'; shapes: ShapeName[] }
  | { kind: 'pattern'; types: ('AB' | 'ABB' | 'AAB' | 'ABC')[] }
  | { kind: 'compare-groups'; max: number }
  | { kind: 'compare-numbers'; max: number; symbols: boolean }
  | { kind: 'size-compare'; attr: 'big' | 'tall' | 'long' | 'heavy' }
  | { kind: 'ten-frame'; max: number }
  | { kind: 'number-bond'; minTotal: number; maxTotal: number }
  | { kind: 'add-pictures'; max: number }
  | { kind: 'sub-pictures'; max: number }
  | { kind: 'facts'; op: '+' | '-' | 'mixed'; max: number; min?: number; three?: boolean; missing?: boolean; doubles?: boolean; makeTen?: boolean }
  | { kind: 'fact-family'; max: number }
  | { kind: 'true-false'; max: number }
  | { kind: 'word-problems'; op: '+' | '-' | 'mixed' | 'compare'; max: number }
  | { kind: 'number-line'; max: number; op: '+' | '-' }
  | { kind: 'place-value'; min: number; max: number }
  | { kind: 'ten-more-less'; max: number }
  | { kind: 'two-digit'; type: 'add-tens' | '2d+1d' | '2d+tens' | 'sub-tens' }
  | { kind: 'hundred-chart'; to: number }
  | { kind: 'skip-count'; by: 2 | 5 | 10; to: number }
  | { kind: 'clock'; half: boolean }
  | { kind: 'coins'; coins: ('penny' | 'nickel' | 'dime' | 'quarter')[]; maxTotal: number }
  | { kind: 'measure'; maxUnits: number }
  | { kind: 'graph'; categories: number }
  | { kind: 'fractions'; parts: (2 | 4)[] }
  | { kind: 'sort'; by: 'color' | 'size' | 'kind' }
  | { kind: 'ordinal' }
  | { kind: 'one-more'; max: number; less?: boolean }

export interface MathTopic {
  week: number
  grade: Grade
  title: string
  strand: string
  standard?: string
  objective: string
  materials: string[]
  teach: string[]
  practice: string[]
  game: string
  check: string
  ifStruggling: string
  ifMastered: string
  easy: string
  gen: MathGen
  review?: boolean
}

type T = Omit<MathTopic, 'grade' | 'week'>

const counters = 'Counters (beans, LEGO, cereal, or buttons)'

