function build(grade: Grade, list: T[]): MathTopic[] {
  if (list.length !== 36) throw new Error(`${grade} math must have 36 weeks, has ${list.length}`)
  return list.map((t, i) => ({ ...t, grade, week: i + 1 }))
}

export const MATH: Record<Grade, MathTopic[]> = {
  'pre-k': build('pre-k', PREK),
  k: build('k', K),
  '1st': build('1st', FIRST),
}

export function getMathWeek(grade: Grade, week: number): MathTopic {
  const list = MATH[grade]
  return list[Math.min(Math.max(week, 1), 36) - 1]
}
